import path from "node:path";
import { test, expect } from "../fixtures/auth";
import {
  STOREFRONT_URL,
  SCREENSHOTS_DIR,
  TEST_REGION_COUNTRY,
} from "../config";

test.describe("B2B bulk-add flow [generated]", () => {
  test("buyer sees quick-order-pad for bulk adding products", async ({
    buyerPage,
  }) => {
    // Step 1: navigate to cart
    await buyerPage.goto(`${STOREFRONT_URL}/${TEST_REGION_COUNTRY}/cart`);
    await buyerPage.waitForLoadState("networkidle");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-bulk-add-01-cart.png"),
    });

    // Step 2: HARD assertion — quick-order-pad section or bulk-add input is visible
    const quickOrderPad = buyerPage.locator('[data-testid="quick-order-pad"]')
      .or(buyerPage.locator('textarea[placeholder*="SKU"], textarea[placeholder*="sku"]').first())
      .or(buyerPage.locator('text=/Quick Order|quick order|bulk/i').first());

    await expect(quickOrderPad).toBeVisible({ timeout: 5000 });
    console.log("[bulk-add] HARD ASSERT 1 PASS: Quick-order-pad visible");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-bulk-add-02-quick-order-pad.png"),
    });

    // Step 3: HARD assertion — input field or button for adding is visible
    const addBtn = buyerPage.locator('[data-testid="quick-order-add-btn"]')
      .or(buyerPage.locator('input[placeholder*="SKU"], textarea').first());

    await expect(addBtn).toBeVisible({ timeout: 5000 });
    console.log("[bulk-add] HARD ASSERT 2 PASS: Add button/input visible");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-bulk-add-03-add-button.png"),
    });

    console.log("[bulk-add] Flow complete — all hard asserts passed");
  });
});
